(2518230, 344827, 22301, '<td valign="top">excellent wide angled shot but I would really loved to have seen the bottom of the river so that we could see the whole "frame" even if you lose some of the sky.</td>', 'excellent wide angled shot but I would really loved to have seen the bottom of the river so that we could see the whole "frame" even if you lose some of the sky.', '2006-06-14 22:02:59.000000', NULL, 1),
(2518231, 346989, 33361, '<td valign="top">very creative...I likey it</td>', 'very creative...I likey it', '2006-06-14 22:03:54.000000', NULL, 1),
(2518232, 347307, 12733, '<td valign="top">Nice picture, nicely framed. I think I would have cropped a lot of the top, maybe enough to show only a small amount of the highway. That would focus attention more on the lighthouse.</td>', 'Nice picture, nicely framed. I think I would have cropped a lot of the top, maybe enough to show only a small amount of the highway. That would focus attention more on the lighthouse.', '2006-06-14 22:04:04.000000', NULL, 1),
(2518235, 346483, 52336, '<td valign="top">Ja, aber</td>', 'Ja, aber', '2006-06-14 22:04:44.000000', NULL, 1),
(2518236, 347453, 33361, '<td valign="top">I hate long explanations/titles...but the image is nice 8</td>', 'I hate long explanations/titles...but the image is nice 8', '2006-06-14 22:04:59.000000', NULL, 1),
(2518237, 345672, 51793, '<td valign="top">Inside the TV is a little dark but I love this idea &amp; the picture turned out well.  Very creative, great job...</td>', 'Inside the TV is a little dark but I love this idea & the picture turned out well.  Very creative, great job...', '2006-06-14 22:04:59.000000', NULL, 1),
(2518238, 346048, 12733, '<td valign="top">Beautiful texture on the "window" frame, and an attractive building inside.</td>', 'Beautiful texture on the "window" frame, and an attractive building inside.', '2006-06-14 22:05:12.000000', NULL, 1),
(2518240, 347273, 52336, '<td valign="top">Really, really needs to be much bigger to be effective.</td>', 'Really, really needs to be much bigger to be effective.', '2006-06-14 22:05:58.000000', NULL, 1),
(2518242, 345731, 33361, '<td valign="top">ouch</td>', 'ouch', '2006-06-14 22:06:17.000000', NULL, 1),
(2518244, 347365, 12733, '<td valign="top">Nice framing, pretty shot. I wold have cropped some off the top to focus better on the runners.</td>', 'Nice framing, pretty shot. I wold have cropped some off the top to focus better on the runners.', '2006-06-14 22:06:32.000000', NULL, 1),
(2518245, 344689, 12733, '<td valign="top">Very nice, clean shot. The "toga" looks staged though, I think more natural clothing would improve the picture.</td>', 'Very nice, clean shot. The "toga" looks staged though, I think more natural clothing would improve the picture.', '2006-06-14 22:07:39.000000', NULL, 1),
(2518246, 346401, 52336, '<td valign="top">Nice picture well composed, but needs to be a bit sharper or more clear.  It''s possible that unsharp mask or similar has created a kind of artefacting around the edges, especially the boy''s face.  Great composition and lovely picture otherwise.</td>', 'Nice picture well composed, but needs to be a bit sharper or more clear.  It''s possible that unsharp mask or similar has created a kind of artefacting around the edges, especially the boy''s face.  Great composition and lovely picture otherwise.', '2006-06-14 22:08:09.000000', NULL, 1),
(2518247, 347354, 33361, '<td valign="top">love the fisheye view... 10</td>', 'love the fisheye view... 10', '2006-06-14 22:08:33.000000', NULL, 1),
(2518248, 346995, 3102, '<td valign="top">I really like the idea, the model, pose, etc., but I would have scored it higher had you framed it in camera, rather than with a big fancy border.  Seems like a bit of a cop-out, I''m afraid.</td>', 'I really like the idea, the model, pose, etc., but I would have scored it higher had you framed it in camera, rather than with a big fancy border.  Seems like a bit of a cop-out, I''m afraid.', '2006-06-14 22:08:52.000000', NULL, 1),
(2518249, 346183, 52336, '<td valign="top">Lots of interesting, intersecting lines within the "frame".  I''d like to have seen more clarity or sharpening, but a nice picture nonetheless.</td>', 'Lots of interesting, intersecting lines within the "frame".  I''d like to have seen more clarity or sharpening, but a nice picture nonetheless.', '2006-06-14 22:09:03.000000', NULL, 1),
(2518250, 346748, 51793, '<td valign="top">I wish I was there!!!  Beautiful...</td>', 'I wish I was there!!!  Beautiful...', '2006-06-14 22:09:35.000000', NULL, 1),
(2518251, 347530, 22301, '<td valign="top">you should try and always use the full allowable 640 pixel limit on your photos, it will help with your scores. Your picture seems out of focus in both the foreground and background, but you found a nice frame and father son moment, I would have nudged over to the right alittle so that none of the family are blocked by vines.</td>', 'you should try and always use the full allowable 640 pixel limit on your photos, it will help with your scores. Your picture seems out of focus in both the foreground and background, but you found a nice frame and father son moment, I would have nudged over to the right alittle so that none of the family are blocked by vines.', '2006-06-14 22:09:39.000000', NULL, 1),
(2518252, 346148, 33361, '<td valign="top">very cool image... 10</td>', 'very cool image... 10', '2006-06-14 22:09:40.000000', NULL, 1),
(2518254, 346746, 33361, '<td valign="top">love the angle - 9</td>', 'love the angle - 9', '2006-06-14 22:10:03.000000', NULL, 1),
(2518255, 346339, 12733, '<td valign="top">Very pretty framing, and I like the boats. I found it difficult to envision this picture as a whole, as it is way too deep for my monitor. I guess it''s a tradeoff in vertical pictures - an imposing size versus the inability of many monitors to encompass the image as a whole.</td>', 'Very pretty framing, and I like the boats. I found it difficult to envision this picture as a whole, as it is way too deep for my monitor. I guess it''s a tradeoff in vertical pictures - an imposing size versus the inability of many monitors to encompass the image as a whole.', '2006-06-14 22:10:38.000000', NULL, 1),
(2518256, 346091, 3102, '<td valign="top">I debated whether or not to give this one a 10, and finally went ahead with it.  This is my favorite shot of the challenge, I do believe.  My only criticism is that I would have cropped it just a little more tightly to eliminate the vertical lines on the right and left.  I think this would have been just a bit better without them, because I find them a little distracting.  Nonetheless, a super shot -- very, very cute (and I''m not much of a dog fan)!</td>', 'I debated whether or not to give this one a 10, and finally went ahead with it.  This is my favorite shot of the challenge, I do believe.  My only criticism is that I would have cropped it just a little more tightly to eliminate the vertical lines on the right and left.  I think this would have been just a bit better without them, because I find them a little distracting.  Nonetheless, a super shot -- very, very cute (and I''m not much of a dog fan)!', '2006-06-14 22:11:46.000000', NULL, 1),
(2518257, 345193, 55642, '<td valign="top">The background is too dark. The "frame" blends too much with it.</td>', 'The background is too dark. The "frame" blends too much with it.', '2006-06-14 22:11:55.000000', NULL, 1),
(2518258, 346526, 33361, '<td valign="top">LOVE IT! 10</td>', 'LOVE IT! 10', '2006-06-14 22:11:58.000000', NULL, 1),
(2518259, 347273, 22301, '<td valign="top"><a href="//dpchallenge.com/tutorial.php?TUTORIAL_ID=26" rel="nofollow" target="_blank">try this link</a>It will show you how to resize images to the max allowable size and your scores will go up.  Also I don''t see whats supposed to be framed, the bricks are leading lines lead to the gap in the plants but then just grass.</td>', 'try this linkIt will show you how to resize images to the max allowable size and your scores will go up.  Also I don''t see whats supposed to be framed, the bricks are leading lines lead to the gap in the plants but then just grass.', '2006-06-14 22:12:14.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2518261, 346245, 12733, '<td valign="top">OK, I won''t take off any points for the bad pun. Great lizard picture, and definitely framed.</td>', 'OK, I won''t take off any points for the bad pun. Great lizard picture, and definitely framed.', '2006-06-14 22:12:27.000000', NULL, 1),
(2518262, 347099, 33361, '<td valign="top">love this image</td>', 'love this image', '2006-06-14 22:12:52.000000', NULL, 1),
(2518264, 346072, 51793, '<td valign="top">It would have been neat if you had the dictionary page on the word ''Frame''</td>', 'It would have been neat if you had the dictionary page on the word ''Frame''', '2006-06-14 22:12:53.000000', NULL, 1),
(2518267, 346812, 12733, '<td valign="top">What a brilliant sunrise. Very pretty.</td>', 'What a brilliant sunrise. Very pretty.', '2006-06-14 22:13:50.000000', NULL, 1),
