(2519260, 347273, 12733, '<td valign="top">This might be a great picture, but at this size it''s hard to tell. In particular, the frame element is not immediately obvious.</td>', 'This might be a great picture, but at this size it''s hard to tell. In particular, the frame element is not immediately obvious.', '2006-06-15 07:21:29.000000', NULL, 1),
