INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2531620, 347606, 60770, '<td valign="top">The framing of the wheel feels too constrictive for the soft photograph.</td>', 'The framing of the wheel feels too constrictive for the soft photograph.', '2006-06-20 11:24:28.000000', NULL, 1),
(2531737, 346536, 60796, '<td valign="top">nice use of lighting</td>', 'nice use of lighting', '2006-06-20 12:16:54.000000', NULL, 1),
(2531754, 347502, 56797, '<td valign="top">the cloudiness in the upper right hand corner kid of takes away from this. fantasttic idea and shot though. way to go. 8</td>', 'the cloudiness in the upper right hand corner kid of takes away from this. fantasttic idea and shot though. way to go. 8', '2006-06-20 12:21:15.000000', NULL, 1),
(2531760, 347544, 56797, '<td valign="top">very cool. i love this. i hope you do well. 9</td>', 'very cool. i love this. i hope you do well. 9', '2006-06-20 12:25:11.000000', NULL, 1),
(2531764, 345672, 56797, '<td valign="top">awesome. 10</td>', 'awesome. 10', '2006-06-20 12:27:31.000000', NULL, 1),
(2531893, 346575, 16230, '<td valign="top">WTG mate! Hope it does well for you! :P</td>', 'WTG mate! Hope it does well for you! :P', '2006-06-20 13:13:42.000000', NULL, 1),
(2531899, 346446, 16230, '<td valign="top">Nice idea. The white sky doesn''t help though. Shooting from a different angle might have worked better.</td>', 'Nice idea. The white sky doesn''t help though. Shooting from a different angle might have worked better.', '2006-06-20 13:19:55.000000', NULL, 1),
(2531908, 347594, 16230, '<td valign="top">Excellent! This should do very well.</td>', 'Excellent! This should do very well.', '2006-06-20 13:26:42.000000', NULL, 1),
(2531922, 347367, 5792, '<td valign="top">Better lighting on the Mermaid''s upper body, perhaps?</td>', 'Better lighting on the Mermaid''s upper body, perhaps?', '2006-06-20 13:33:09.000000', NULL, 1),
(2531924, 346772, 5792, '<td valign="top">Might be even better if the top of the foreground piper were highlighted more.</td>', 'Might be even better if the top of the foreground piper were highlighted more.', '2006-06-20 13:33:51.000000', NULL, 1),
(2531928, 347584, 5792, '<td valign="top">Not every Haystack Rock picture will win a ribbon but a nice sihlouette with the trees. Would work really well at sunset. :)</td>', 'Not every Haystack Rock picture will win a ribbon but a nice sihlouette with the trees. Would work really well at sunset. :)', '2006-06-20 13:34:44.000000', NULL, 1),
(2531930, 346526, 5792, '<td valign="top">Nice lighting, good brown tones, good facial tones and decent framing except for cutting off the top of the baby''s head. In most images you reserve sharpest focus for the most important element in the image. In this case that is implied to be the baby''s hand. Might be a stronger composition if the baby''s face were in sharpest focus instead.</td>', 'Nice lighting, good brown tones, good facial tones and decent framing except for cutting off the top of the baby''s head. In most images you reserve sharpest focus for the most important element in the image. In this case that is implied to be the baby''s hand. Might be a stronger composition if the baby''s face were in sharpest focus instead.', '2006-06-20 13:35:45.000000', NULL, 1),
(2531960, 347081, 16004, '<td valign="top">this is a very stylish and swanky portrait.  its simplicity is its strongest point; the composition is nice, tidy, and has immediate impact.  a dumb thing to complain about, but the tripod looks a bit too modern and the lever arm thingy is a bit too prominent...  everything else is very nice.  i like the tones, and i love the frame and how it''s strung up - i think something would have been lost if you could and did clone out the strings.   did you actually use the camera to take a picture of the camera taking a picture of you?   8.</td>', 'this is a very stylish and swanky portrait.  its simplicity is its strongest point; the composition is nice, tidy, and has immediate impact.  a dumb thing to complain about, but the tripod looks a bit too modern and the lever arm thingy is a bit too prominent...  everything else is very nice.  i like the tones, and i love the frame and how it''s strung up - i think something would have been lost if you could and did clone out the strings.   did you actually use the camera to take a picture of the camera taking a picture of you?   8.', '2006-06-20 13:47:50.000000', NULL, 1),
(2531976, 347287, 16004, '<td valign="top">do vampires wear jeans?  and isn''t it a bit dodgy to be out in daylight?  minor points for an enjoyably interesting photograph.  the angle becomes it''s main feature, of course, due to the extremety of it; but i think it works in this case, it feels a natural choice and not at all forced.  it''s a good applicatoion of the environment, and it fits the challenge really well.  might have gone for a slightly squarer crop, possibly from the top of the straw, and also a bit of noise reduction to soften some of the harsher edges.  overall though, very likeable.  7.</td>', 'do vampires wear jeans?  and isn''t it a bit dodgy to be out in daylight?  minor points for an enjoyably interesting photograph.  the angle becomes it''s main feature, of course, due to the extremety of it; but i think it works in this case, it feels a natural choice and not at all forced.  it''s a good applicatoion of the environment, and it fits the challenge really well.  might have gone for a slightly squarer crop, possibly from the top of the straw, and also a bit of noise reduction to soften some of the harsher edges.  overall though, very likeable.  7.', '2006-06-20 13:54:58.000000', NULL, 1),
(2531985, 346446, 16004, '<td valign="top">it''s a nice action shot, but i think using the fence as a frame doesn''t really work aesthetically.  there seems to be some fringing too, which i think might be reduceable with a bit of noise reduction software.  it''s a pity that the rules don''t let you blur the background a bit, as i think it takes away attention from the lads.  forgetting the frame element of the picture, it''s otherwise quite captivating - it has a story, a certain depth, and is fun.  you care if the ball is caught or not (though the title is a giveaway - should have called it "Strike?" :) ).  6.</td>', 'it''s a nice action shot, but i think using the fence as a frame doesn''t really work aesthetically.  there seems to be some fringing too, which i think might be reduceable with a bit of noise reduction software.  it''s a pity that the rules don''t let you blur the background a bit, as i think it takes away attention from the lads.  forgetting the frame element of the picture, it''s otherwise quite captivating - it has a story, a certain depth, and is fun.  you care if the ball is caught or not (though the title is a giveaway - should have called it "Strike?" :) ).  6.', '2006-06-20 14:00:05.000000', NULL, 1),
(2531988, 346091, 60839, '<td valign="top">A great shot but so sad!</td>', 'A great shot but so sad!', '2006-06-20 14:01:27.000000', NULL, 1),
(2531992, 346995, 60839, '<td valign="top">Interesting framing I like it - I love off center photography something about it.....</td>', 'Interesting framing I like it - I love off center photography something about it.....', '2006-06-20 14:02:35.000000', NULL, 1),
(2532004, 347446, 38198, '<td valign="top">Like this shot, fits the challenge well. But it is too small to get a good score. Go to Learn/tutorials you will find a tutorial on how to set up your photo for DPC. I make this mistake my first 2 entrys, someone gave me this advice and wow does it ever help. Good Luck</td>', 'Like this shot, fits the challenge well. But it is too small to get a good score. Go to Learn/tutorials you will find a tutorial on how to set up your photo for DPC. I make this mistake my first 2 entrys, someone gave me this advice and wow does it ever help. Good Luck', '2006-06-20 14:07:50.000000', NULL, 1),
(2532007, 345390, 16004, '<td valign="top">i hope other voters take the time to look at your picture and not dismiss it at a stroke.  i nearly did myself - i didn''t register the frame for a moment there...  but yes, the sky does form a natural frame of sorts, and a quite stunningly beautiful one at that.  i think whacking up the contrast, or even taking up the saturation and lowering the lightness on the blues (which you can do under basic) would have made it a bit more obvious, though.  your subject seems to be quite an enigmatic character - i was compelled to look him up actually.  the statue is beautifully lit, and nicely captured - good for a guide book.  nice - 7.</td>', 'i hope other voters take the time to look at your picture and not dismiss it at a stroke.  i nearly did myself - i didn''t register the frame for a moment there...  but yes, the sky does form a natural frame of sorts, and a quite stunningly beautiful one at that.  i think whacking up the contrast, or even taking up the saturation and lowering the lightness on the blues (which you can do under basic) would have made it a bit more obvious, though.  your subject seems to be quite an enigmatic character - i was compelled to look him up actually.  the statue is beautifully lit, and nicely captured - good for a guide book.  nice - 7.', '2006-06-20 14:08:25.000000', NULL, 1),
(2532012, 347606, 38198, '<td valign="top">Wow, I love the setting. Good light ...</td>', 'Wow, I love the setting. Good light ...', '2006-06-20 14:09:40.000000', NULL, 1),
(2532013, 346891, 38198, '<td valign="top">What can I say but Ohhhh Ahhhh 10...10....</td>', 'What can I say but Ohhhh Ahhhh 10...10....', '2006-06-20 14:10:35.000000', NULL, 1),
(2532019, 347483, 38198, '<td valign="top">This subject has been done so much but you make it come alive agin. Nice Job! 10</td>', 'This subject has been done so much but you make it come alive agin. Nice Job! 10', '2006-06-20 14:11:37.000000', NULL, 1),
(2532021, 346794, 16004, '<td valign="top">appears very professionally done - almost a bit too much if that makes any sense.  the frame actually saves it from being another kind of portrait you see in the high street, it''s a great ornate beast of a frame, isn''t it?  goes with the colours of the velvetish material and the sprog very well; the tones are all very complementary.  might have cropped three or four millimeters off the bottom, but other than that, wouldn''t touch it.  great shot for any parent to hang on the wall (frameless canvas, naturally!)  8</td>', 'appears very professionally done - almost a bit too much if that makes any sense.  the frame actually saves it from being another kind of portrait you see in the high street, it''s a great ornate beast of a frame, isn''t it?  goes with the colours of the velvetish material and the sprog very well; the tones are all very complementary.  might have cropped three or four millimeters off the bottom, but other than that, wouldn''t touch it.  great shot for any parent to hang on the wall (frameless canvas, naturally!)  8', '2006-06-20 14:12:48.000000', NULL, 1),
(2532023, 347087, 38198, '<td valign="top">This is so cute and fits just right in the challenge, sharp clear good design. This shot is a 10 for me.</td>', 'This is so cute and fits just right in the challenge, sharp clear good design. This shot is a 10 for me.', '2006-06-20 14:13:03.000000', NULL, 1),
(2532031, 346151, 38198, '<td valign="top">This is a work of art. Nice clear color, I like the effects. I would think you will get  high score with this shot.</td>', 'This is a work of art. Nice clear color, I like the effects. I would think you will get  high score with this shot.', '2006-06-20 14:15:14.000000', NULL, 1),
(2532035, 347285, 38198, '<td valign="top">Nice, love the color works well with this one.</td>', 'Nice, love the color works well with this one.', '2006-06-20 14:16:22.000000', NULL, 1),
(2532037, 346803, 38198, '<td valign="top">This is so cool doen''t look real! 10</td>', 'This is so cool doen''t look real! 10', '2006-06-20 14:17:18.000000', NULL, 1),
(2532041, 347367, 38198, '<td valign="top">Good name. Wonderful shot.</td>', 'Good name. Wonderful shot.', '2006-06-20 14:19:07.000000', NULL, 1),
(2532043, 347368, 16004, '<td valign="top">very clever!  nice titling and use of what''s in the frame!  i''m taken aback in wonder at your cleverness - inspired!  there sn''t much to criticise about this.  i guess due to the circumstances of the photo - right time, right place - you were probably limited with what you could do, but i think the man at the back would ideally be a bit more of a prominent feature in the shot.  but in order to fit it in, not a lot you could do...  7.</td>', 'very clever!  nice titling and use of what''s in the frame!  i''m taken aback in wonder at your cleverness - inspired!  there sn''t much to criticise about this.  i guess due to the circumstances of the photo - right time, right place - you were probably limited with what you could do, but i think the man at the back would ideally be a bit more of a prominent feature in the shot.  but in order to fit it in, not a lot you could do...  7.', '2006-06-20 14:19:20.000000', NULL, 1),
(2532051, 346748, 38198, '<td valign="top">This is a wonderful photo, I wish I was there.</td>', 'This is a wonderful photo, I wish I was there.', '2006-06-20 14:21:31.000000', NULL, 1),
(2532054, 346794, 38198, '<td valign="top">Cute what a good idea.</td>', 'Cute what a good idea.', '2006-06-20 14:21:56.000000', NULL, 1),
(2532055, 347278, 16004, '<td valign="top">the lighting and the whiteness of the picture is very soothingly pleasing (yes, very zen-like).  it''s a shame the chopsticks aren''t any more defined - i think your score might suffer as a result.  the almost panoramic crop also makes the picture too cramped and confined.  5.</td>', 'the lighting and the whiteness of the picture is very soothingly pleasing (yes, very zen-like).  it''s a shame the chopsticks aren''t any more defined - i think your score might suffer as a result.  the almost panoramic crop also makes the picture too cramped and confined.  5.', '2006-06-20 14:22:24.000000', NULL, 1),
(2532061, 346867, 38198, '<td valign="top">Too cute. You got this cat lovers vote.</td>', 'Too cute. You got this cat lovers vote.', '2006-06-20 14:23:27.000000', NULL, 1),
(2532066, 346780, 16004, '<td valign="top">goodness, he''s looking old...  to be honest, i think this is sitting on the borders as to meeting the challenge or not; i mean, it does, the mic stand and the guitar are clearly the elements of the frame, but i don''t think the protrait is necessarily enhanced by the presence of these things.  he also looks like a small bloke dwarfed by a microphone.  nice as a rock pic though.  6.</td>', 'goodness, he''s looking old...  to be honest, i think this is sitting on the borders as to meeting the challenge or not; i mean, it does, the mic stand and the guitar are clearly the elements of the frame, but i don''t think the protrait is necessarily enhanced by the presence of these things.  he also looks like a small bloke dwarfed by a microphone.  nice as a rock pic though.  6.', '2006-06-20 14:26:33.000000', NULL, 1),
(2532084, 346252, 16004, '<td valign="top">hee - i initially thought the horses were the snack!  (for obvius reasons) the lighting is too dark really.  you could fix this a bit using levels (i assume you have photoshop elements) - try 0-1.60-223 on the RGB channel and  0-0.69-219 on the blue channel; i think it might improve the colours a bit without blowing out the moon too much.  it also makes the difference between the bush and the grass more obvious, therefore making the framing element more obvious (i initially thought the moon was the thing being framed with other stuff going on).  5.</td>', 'hee - i initially thought the horses were the snack!  (for obvius reasons) the lighting is too dark really.  you could fix this a bit using levels (i assume you have photoshop elements) - try 0-1.60-223 on the RGB channel and  0-0.69-219 on the blue channel; i think it might improve the colours a bit without blowing out the moon too much.  it also makes the difference between the bush and the grass more obvious, therefore making the framing element more obvious (i initially thought the moon was the thing being framed with other stuff going on).  5.', '2006-06-20 14:34:15.000000', NULL, 1),
(2532085, 346072, 38198, '<td valign="top">Good idea! Wow like this a lot.</td>', 'Good idea! Wow like this a lot.', '2006-06-20 14:34:16.000000', NULL, 1),
(2532093, 347045, 38198, '<td valign="top">I think I would like this more if it were in focus. I like the idea, and the colors.</td>', 'I think I would like this more if it were in focus. I like the idea, and the colors.', '2006-06-20 14:39:49.000000', NULL, 1),
(2532099, 345193, 16004, '<td valign="top">this is actually bordering on bonkers.  took me a few moments to see that the head doesn''t seem to belong to the body holding it up.  and also, the green light on the monitor is a bit unnerving.  i can''t quite figure out what the concet actually is, to be honest.  i guess this makes it art!  i like it though, it has a very modernist feel, and some depth in a philisophical sense - well beyond my brain, obvoiusly, but i can see something deep is going on.  only comment about the technical bits are that for me the contrast is a bit too contrasty, but i like the unconventional crop (though might have been tempted to lose the stuff below the elbows) and wonkiness.  it''s a striking composition - 7.</td>', 'this is actually bordering on bonkers.  took me a few moments to see that the head doesn''t seem to belong to the body holding it up.  and also, the green light on the monitor is a bit unnerving.  i can''t quite figure out what the concet actually is, to be honest.  i guess this makes it art!  i like it though, it has a very modernist feel, and some depth in a philisophical sense - well beyond my brain, obvoiusly, but i can see something deep is going on.  only comment about the technical bits are that for me the contrast is a bit too contrasty, but i like the unconventional crop (though might have been tempted to lose the stuff below the elbows) and wonkiness.  it''s a striking composition - 7.', '2006-06-20 14:43:10.000000', NULL, 1),
(2532108, 345401, 29148, '<td valign="top">I like the shot a lot, would have given you a better score if I could see some framing involved in the composition.</td>', 'I like the shot a lot, would have given you a better score if I could see some framing involved in the composition.', '2006-06-20 14:47:03.000000', NULL, 1),
(2532110, 347087, 29148, '<td valign="top">Nice composition. The colors of her fingers are quite distracting.</td>', 'Nice composition. The colors of her fingers are quite distracting.', '2006-06-20 14:48:30.000000', NULL, 1),
(2532124, 347524, 16004, '<td valign="top">this is so simple it''s a wonder no one else did it.  it''s brillant; complies with the challenge, expertly taken and it works.  it''s playful, fun, and is a good portrait.  i like how the lighting on the hands is lighter than the face, as it adds a sense of distance and depth...  i think i might like the hands to be a little blurrier and the facial features a smidgeon sharper, but that aside a good solid spiffing picture.  8.</td>', 'this is so simple it''s a wonder no one else did it.  it''s brillant; complies with the challenge, expertly taken and it works.  it''s playful, fun, and is a good portrait.  i like how the lighting on the hands is lighter than the face, as it adds a sense of distance and depth...  i think i might like the hands to be a little blurrier and the facial features a smidgeon sharper, but that aside a good solid spiffing picture.  8.', '2006-06-20 14:54:36.000000', NULL, 1),
